param([string]$RepositoryRoot = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path)
$ErrorActionPreference='Stop'; $snapshotRoot=Join-Path $RepositoryRoot 'tests/e2e/frontend-operations-approvals/snapshots'; $outputPath=Join-Path $RepositoryRoot 'docs/evidence/frontend/operations-approvals-visual-baseline.json'
$snapshots=@(Get-ChildItem -LiteralPath $snapshotRoot -Filter 'PV-*.png'|Sort-Object Name); if($snapshots.Count -ne 28){throw "Expected exactly 28 approval snapshots, found $($snapshots.Count)."}
$cases=foreach($snapshot in $snapshots){$pv=[IO.Path]::GetFileNameWithoutExtension($snapshot.Name); [ordered]@{pv=$pv;pageId='operations.approvals';testId="operations-approvals-visual.spec.ts::$pv";baselinePath=$snapshot.FullName.Substring($RepositoryRoot.Length+1).Replace('\','/');sha256=(Get-FileHash -LiteralPath $snapshot.FullName -Algorithm SHA256).Hash.ToLowerInvariant();bytes=$snapshot.Length}}
if(@($cases.sha256|Sort-Object -Unique).Count -ne 28){throw 'Approval snapshots must have 28 unique hashes.'}
$evidence=[ordered]@{schemaVersion=1;evidenceType='frontend-visual-regression-baseline';generatedAt=[DateTimeOffset]::UtcNow.ToString('o');sourceCommit=(git -C $RepositoryRoot rev-parse HEAD).Trim();contractVersion='operations-approvals-design-1.0';baselineVersion='operations-approvals-windows-chromium-v1';environment=[ordered]@{operatingSystem='Windows';browser='Chromium';viewport='1440x900';locale='zh-CN';timezone='Asia/Shanghai';colorScheme='light';reducedMotion=$true};businessAssertions=@('复兴银行运营控制台覆盖 PV-0108 至 PV-0135 的 28 个审批状态。','审批队列来自 transfer_reversal 持久化数据，并使用生成式 operations API 客户端。','批准和拒绝均要求审批理由、幂等键、Checker 权限与当前版本。','拒绝冲正会把交易从 REVERSAL_PENDING 恢复为 SETTLED，批准会执行补偿交易并进入 REVERSED。','视觉状态覆盖加载、空数据、待审批、无权限、版本冲突、抽屉、确认、提交及结果。','视觉数据为确定性合成数据，不包含真实个人信息或密钥。');cases=$cases}
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $outputPath)|Out-Null;$utf8NoBom=New-Object Text.UTF8Encoding($false);[IO.File]::WriteAllText($outputPath,($evidence|ConvertTo-Json -Depth 8),$utf8NoBom);Write-Output $outputPath
